 ('E13','Chen, J., et al.','2024','LLMArena: Assessing Capabilities of Large Language Models in Dynamic Multi-Agent Environments','https://aclanthology.org/2024.acl-long.705/','ACL 2024','Primary abstract and publication record','Comparative agent evaluation in seven multi-agent games.'),
 ('E14','Zhu, A., Osgood, E., and Callison-Burch, C.','2025','First Steps Towards Overhearing LLM Agents: A Case Study With Dungeons & Dragons Gameplay','https://arxiv.org/abs/2505.22809v2','COLM 2025 Workshop on AI Agents; arXiv v2','Primary abstract and publication record','Background assistance around human play, distinct from occupying a player seat.'),
